/* ============================================================================
   Embedded Google Sans — base64 TTF, extracted verbatim from the pre-migration
   src/legacy/shared.js. Used by BOTH the PDF (jsPDF addFont) and the web @font-face.
   "Google Sans" is proprietary and not on the public Google Fonts API, so it can't
   be linked — these bytes are the only source. Kept eager (not a lazy chunk): the UI
   @font-face below needs all four faces at startup. jsPDF / SheetJS are the lazy libs.
   ============================================================================ */

export const PA_GOOGLE_SANS_REGULAR = '';
export const PA_GOOGLE_SANS_BOLD = '';
export const PA_GOOGLE_SANS_ITALIC = '';
export const PA_GOOGLE_SANS_BOLDITALIC = '';

/* Register the four faces into a jsPDF instance (call once per doc before use). */
export function registerGoogleSansFonts(doc: any): void {
  doc.addFileToVFS('GoogleSans-Regular.ttf', PA_GOOGLE_SANS_REGULAR);
  doc.addFont('GoogleSans-Regular.ttf', 'GoogleSans', 'normal');
  doc.addFileToVFS('GoogleSans-Bold.ttf', PA_GOOGLE_SANS_BOLD);
  doc.addFont('GoogleSans-Bold.ttf', 'GoogleSans', 'bold');
  doc.addFileToVFS('GoogleSans-Italic.ttf', PA_GOOGLE_SANS_ITALIC);
  doc.addFont('GoogleSans-Italic.ttf', 'GoogleSans', 'italic');
  doc.addFileToVFS('GoogleSans-BoldItalic.ttf', PA_GOOGLE_SANS_BOLDITALIC);
  doc.addFont('GoogleSans-BoldItalic.ttf', 'GoogleSans', 'bolditalic');
}

/* Make the WEB genuinely use Google Sans (the public Google Fonts API does NOT host it — the old
   <link> silently fell back to Inter). Reuse the embedded base64 TTFs as @font-face data URIs —
   real Google Sans, offline-safe. Only Regular (400) + Bold (700) exist, so weight ranges map
   400–500→Regular and 600–900→Bold. System fallback after it covers Thai glyphs, which Google
   Sans lacks. Called once from main.ts at startup. */
export function registerGoogleSansWebFont(): void {
  if (document.getElementById('pa-google-sans-face')) return;
  // unicode-range defaults to U+0-10FFFF (everything) when omitted — that was the actual bug here:
  // it made these @font-face rules claim the Thai block too, so the browser never even tried the
  // second font-family in the CSS stack ('Noto Sans Thai', unicode-range-scoped to Thai, see
  // main.ts) for Thai text. unicode-range only gates which characters a face is TRIED for, not
  // whether the font file has a glyph for them — Google Sans's TTF has no Thai glyphs, so Thai
  // characters were silently falling through to the browser's own default system font instead of
  // ever reaching Noto Sans Thai. Excluding the Thai block (and its combining marks) here is what
  // lets the family-list fallback to 'Noto Sans Thai' actually happen.
  const LATIN_RANGE = 'U+0-0DFF,U+0E5C-10FFFF';
  const src = (b64: string, style: string, wLo: number, wHi: number) =>
    `@font-face{font-family:'Google Sans';font-style:${style};font-weight:${wLo} ${wHi};` +
    `unicode-range:${LATIN_RANGE};` +
    `font-display:swap;src:url(data:font/ttf;base64,${b64}) format('truetype');}`;
  const css =
    src(PA_GOOGLE_SANS_REGULAR, 'normal', 400, 500) +
    src(PA_GOOGLE_SANS_BOLD, 'normal', 600, 900) +
    src(PA_GOOGLE_SANS_ITALIC, 'italic', 400, 500) +
    src(PA_GOOGLE_SANS_BOLDITALIC, 'italic', 600, 900);
  const style = document.createElement('style');
  style.id = 'pa-google-sans-face';
  style.textContent = css;
  (document.head || document.documentElement).appendChild(style);
}


/* ============================================================================
   Thai PDF text support — Noto Sans Thai (OFL-1.1, Google's official variable
   TTF, src/assets/fonts/NotoSansThai.ttf). Google Sans has no Thai glyphs, so
   without this, Thai text in a finding (location, notes, etc.) renders as
   missing/garbled glyphs in the exported PDF. Lazy: fetched only when a PDF is
   actually built (via Vite's ?url asset import), same dynamic-loading posture
   as jsPDF itself — never bundled into the eager entry chunk.
   ============================================================================ */
import notoSansThaiUrl from '../assets/fonts/NotoSansThai.ttf?url';

const THAI_RANGE = /[ก-๛]/;

let thaiFontB64: string | null = null;
async function ensureThaiFont(): Promise<string> {
  if (thaiFontB64) return thaiFontB64;
  const buf = await (await fetch(notoSansThaiUrl)).arrayBuffer();
  let binary = '';
  const bytes = new Uint8Array(buf);
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunk));
  }
  thaiFontB64 = btoa(binary);
  return thaiFontB64;
}

// text can be a string OR an array of strings (doc.text accepts pre-wrapped lines from
// splitTextToSize) — treat any Thai codepoint anywhere in it as "this call needs the Thai font".
function containsThai(text: any): boolean {
  if (typeof text === 'string') return THAI_RANGE.test(text);
  if (Array.isArray(text)) return text.some(t => typeof t === 'string' && THAI_RANGE.test(t));
  return false;
}

/* Registers NotoSansThai into the jsPDF instance and wraps doc.text + doc.splitTextToSize so any
   string (or array of strings) containing Thai codepoints (U+0E01-U+0E5B) is measured/drawn with
   it instead of whatever font is currently set — Latin/numeric-only strings are completely
   unaffected, so none of the app's ~49 existing doc.text()/splitTextToSize() call sites need to
   change. Both wrappers matter: splitTextToSize measures glyph widths at CALL time to decide line
   breaks, so if it runs under GoogleSans (which has zero Thai glyphs) the wrapped lines are already
   wrong by the time doc.text sees them — patching text() alone silently drops Thai text pre-wrapped
   this way (row() in pdf.ts is exactly this pattern). Call once per doc, after
   registerGoogleSansFonts(doc). */
export async function registerThaiPdfFont(doc: any): Promise<void> {
  const b64 = await ensureThaiFont();
  doc.addFileToVFS('NotoSansThai.ttf', b64);
  doc.addFont('NotoSansThai.ttf', 'NotoSansThai', 'normal');
  doc.addFont('NotoSansThai.ttf', 'NotoSansThai', 'bold'); // single weight; jsPDF needs a 'bold' entry to satisfy setFont('...', 'bold') calls

  const originalText = doc.text.bind(doc);
  const originalSplit = doc.splitTextToSize.bind(doc);
  const originalSetFont = doc.setFont.bind(doc);
  let currentFont = 'GoogleSans';
  let currentStyle = 'normal';
  doc.setFont = (name: string, style?: string) => {
    if (name !== 'NotoSansThai') { currentFont = name; currentStyle = style || 'normal'; }
    return originalSetFont(name, style);
  };
  const withThaiFont = (fn: () => any) => {
    originalSetFont('NotoSansThai', currentStyle === 'bold' ? 'bold' : 'normal');
    const result = fn();
    originalSetFont(currentFont, currentStyle);
    return result;
  };
  doc.text = (text: any, ...rest: any[]) =>
    containsThai(text) ? withThaiFont(() => originalText(text, ...rest)) : originalText(text, ...rest);
  doc.splitTextToSize = (text: any, ...rest: any[]) =>
    containsThai(text) ? withThaiFont(() => originalSplit(text, ...rest)) : originalSplit(text, ...rest);
}
